20260514153126	{"CREATE TABLE kiva_registrations (\n    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),\n    project_id UUID REFERENCES projects(id) ON DELETE CASCADE,\n    is_ilj_volunteer BOOLEAN DEFAULT false,\n    ilj_id TEXT,\n    full_name TEXT NOT NULL,\n    mobile_number TEXT NOT NULL,\n    preferred_dates TEXT NOT NULL,\n    created_at TIMESTAMPTZ DEFAULT NOW()\n);\n\n-- Policies\nALTER TABLE kiva_registrations ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \\"Allow public inserts on kiva_registrations\\"\nON kiva_registrations FOR INSERT TO public\nWITH CHECK (true);\n\nCREATE POLICY \\"Allow authenticated reads on kiva_registrations\\"\nON kiva_registrations FOR SELECT TO authenticated\nUSING (true);\n"}	kiva_registrations	meets.studentlife@gmail.com	\N	\N
20260603153110	{"CREATE TABLE IF NOT EXISTS public.pathshalas (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    name TEXT NOT NULL,\n    sangh_name TEXT NOT NULL,\n    contact_person TEXT NOT NULL,\n    mobile_number TEXT NOT NULL,\n    email TEXT NOT NULL,\n    address TEXT NOT NULL,\n    city TEXT NOT NULL,\n    state TEXT NOT NULL,\n    pincode TEXT NOT NULL,\n    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL\n);\n\nCREATE TABLE IF NOT EXISTS public.library_books (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    book_no TEXT UNIQUE NOT NULL,\n    book_name TEXT NOT NULL,\n    author TEXT,\n    publisher TEXT,\n    language TEXT,\n    set_no TEXT,\n    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL\n);\n\nCREATE TABLE IF NOT EXISTS public.pathshala_assignments (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    pathshala_id UUID REFERENCES public.pathshalas(id) ON DELETE CASCADE NOT NULL,\n    set_no TEXT NOT NULL,\n    date_of_issue DATE NOT NULL,\n    date_of_renewal DATE NOT NULL,\n    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL\n);"}	create_library_tables	meets.studentlife@gmail.com	\N	\N
20260616173206	{"-- Create kiva_sessions table\nCREATE TABLE IF NOT EXISTS public.kiva_sessions (\n    id uuid DEFAULT gen_random_uuid() NOT NULL,\n    date date NOT NULL,\n    time time without time zone NOT NULL,\n    venue text NOT NULL,\n    created_at timestamp with time zone DEFAULT now(),\n    updated_at timestamp with time zone DEFAULT now(),\n    CONSTRAINT kiva_sessions_pkey PRIMARY KEY (id)\n);\n\n-- Enable RLS on kiva_sessions\nALTER TABLE public.kiva_sessions ENABLE ROW LEVEL SECURITY;\n\n-- Create policies for kiva_sessions\nDROP POLICY IF EXISTS \\"Allow public select kiva_sessions\\" ON public.kiva_sessions;\nCREATE POLICY \\"Allow public select kiva_sessions\\" ON public.kiva_sessions FOR SELECT USING (true);\n\nDROP POLICY IF EXISTS \\"Allow admin manage kiva_sessions\\" ON public.kiva_sessions;\nCREATE POLICY \\"Allow admin manage kiva_sessions\\" ON public.kiva_sessions FOR ALL TO authenticated USING (is_admin()) WITH CHECK (is_admin());\n\n-- Grant privileges on kiva_sessions\nGRANT ALL ON TABLE public.kiva_sessions TO authenticated, service_role;\nGRANT SELECT ON TABLE public.kiva_sessions TO anon;\n\n-- Alter kiva_registrations to add attendance columns\nALTER TABLE public.kiva_registrations ADD COLUMN IF NOT EXISTS attendance_status text DEFAULT 'Not Attended';\nALTER TABLE public.kiva_registrations ADD COLUMN IF NOT EXISTS attended_event_id uuid REFERENCES public.kiva_sessions(id) ON DELETE SET NULL;\n\n-- Create UPDATE policy on kiva_registrations\nDROP POLICY IF EXISTS \\"Allow admin updates on kiva_registrations\\" ON public.kiva_registrations;\nCREATE POLICY \\"Allow admin updates on kiva_registrations\\" ON public.kiva_registrations FOR UPDATE TO authenticated USING (is_admin()) WITH CHECK (is_admin());\n\n-- Create INSERT policy on notifications if not exists\nDROP POLICY IF EXISTS \\"Allow authenticated inserts on notifications\\" ON public.notifications;\nCREATE POLICY \\"Allow authenticated inserts on notifications\\" ON public.notifications FOR INSERT TO authenticated WITH CHECK (true);"}	setup_kiva_sessions_and_attendance	meets.studentlife@gmail.com	\N	\N
20260616175247	{"CREATE OR REPLACE FUNCTION public.get_user_privilege_level()\n RETURNS text\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nDECLARE\n    v_role text;\n    v_is_leader boolean;\n    v_is_manager boolean;\n    v_is_it_admin boolean;\nBEGIN\n    -- 1. Check Explicit Roles (app_roles)\n    SELECT role INTO v_role FROM public.app_roles WHERE user_id = auth.uid() LIMIT 1;\n    IF v_role IS NOT NULL THEN\n        RETURN v_role; -- 'admin', 'manager', 'team_leader'\n    END IF;\n\n    -- 2. Check IT Admin Status (volunteers.is_it_admin)\n    SELECT is_it_admin INTO v_is_it_admin\n    FROM public.volunteers\n    WHERE id = auth.uid();\n\n    IF v_is_it_admin = true THEN\n        RETURN 'admin';\n    END IF;\n\n    -- 3. Check Dynamic Manager Status (projects.manager_id)\n    -- Managers should have higher privilege than team leaders implicitly\n    SELECT EXISTS(SELECT 1 FROM public.projects WHERE manager_id = auth.uid()) INTO v_is_manager;\n    \n    IF v_is_manager THEN\n        RETURN 'manager';\n    END IF;\n\n    -- 4. Check Dynamic Leader Status (volunteers.team_leader_for)\n    SELECT (team_leader_for IS NOT NULL AND team_leader_for != '') INTO v_is_leader\n    FROM public.volunteers \n    WHERE id = auth.uid();\n    \n    IF v_is_leader THEN\n        RETURN 'team_leader';\n    END IF;\n\n    -- Default\n    RETURN 'volunteer';\nEND;\n$function$;"}	update_get_user_privilege_level_for_it_admins	meets.studentlife@gmail.com	\N	\N
20260926182311	{"-- 1. Function to suspend volunteer account\nCREATE OR REPLACE FUNCTION public.suspend_volunteer(p_volunteer_id uuid)\nRETURNS json\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public', 'auth'\nAS $$\nBEGIN\n    IF NOT EXISTS (SELECT 1 FROM public.volunteers WHERE id = p_volunteer_id) THEN\n        RETURN json_build_object('success', false, 'error', 'Volunteer not found');\n    END IF;\n\n    UPDATE public.volunteers\n    SET activity_status = 'Suspended',\n        updated_at = now()\n    WHERE id = p_volunteer_id;\n\n    UPDATE auth.users\n    SET banned_until = '3000-01-01 00:00:00+00'\n    WHERE id = p_volunteer_id;\n\n    RETURN json_build_object('success', true, 'message', 'Volunteer account suspended successfully');\nEXCEPTION WHEN OTHERS THEN\n    RETURN json_build_object('success', false, 'error', SQLERRM);\nEND;\n$$;\n\n-- 2. Function to reactivate/unsuspend volunteer account\nCREATE OR REPLACE FUNCTION public.reactivate_volunteer(p_volunteer_id uuid)\nRETURNS json\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public', 'auth'\nAS $$\nBEGIN\n    IF NOT EXISTS (SELECT 1 FROM public.volunteers WHERE id = p_volunteer_id) THEN\n        RETURN json_build_object('success', false, 'error', 'Volunteer not found');\n    END IF;\n\n    UPDATE public.volunteers\n    SET activity_status = 'Active',\n        updated_at = now()\n    WHERE id = p_volunteer_id;\n\n    UPDATE auth.users\n    SET banned_until = NULL\n    WHERE id = p_volunteer_id;\n\n    RETURN json_build_object('success', true, 'message', 'Volunteer account reactivated successfully');\nEXCEPTION WHEN OTHERS THEN\n    RETURN json_build_object('success', false, 'error', SQLERRM);\nEND;\n$$;\n\n-- 3. Function to permanently terminate volunteer account\nCREATE OR REPLACE FUNCTION public.terminate_volunteer(p_volunteer_id uuid)\nRETURNS json\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public', 'auth'\nAS $$\nDECLARE\n    v_volunteer public.volunteers%ROWTYPE;\nBEGIN\n    SELECT * INTO v_volunteer FROM public.volunteers WHERE id = p_volunteer_id;\n    IF v_volunteer.id IS NULL THEN\n        RETURN json_build_object('success', false, 'error', 'Volunteer not found');\n    END IF;\n\n    -- Unlink project management if manager or sub-head\n    UPDATE public.projects \n    SET manager_id = NULL \n    WHERE manager_id = p_volunteer_id;\n\n    UPDATE public.projects \n    SET sub_head_ids = array_remove(sub_head_ids, p_volunteer_id) \n    WHERE p_volunteer_id = ANY(sub_head_ids);\n\n    -- Remove from app_roles if present\n    DELETE FROM public.app_roles WHERE user_id = p_volunteer_id;\n\n    -- Delete from public.volunteers (cascades to related tables like timesheets, notifications)\n    DELETE FROM public.volunteers WHERE id = p_volunteer_id;\n\n    -- Delete from auth.users (cascades to identities, sessions)\n    DELETE FROM auth.users WHERE id = p_volunteer_id;\n\n    RETURN json_build_object('success', true, 'message', 'Volunteer account permanently terminated');\nEXCEPTION WHEN OTHERS THEN\n    RETURN json_build_object('success', false, 'error', SQLERRM);\nEND;\n$$;\n\n-- 4. Update login_volunteer to block suspended volunteers\nCREATE OR REPLACE FUNCTION public.login_volunteer(p_ilj_id text, p_password text)\n RETURNS json\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    v_user record;\n    v_password_match boolean;\nBEGIN\n    SELECT * INTO v_user\n    FROM public.volunteers\n    WHERE upper(ilj_id) = upper(p_ilj_id);\n\n    IF v_user IS NULL THEN\n        RETURN json_build_object('success', false, 'error', 'Invalid ILJ ID or password');\n    END IF;\n\n    IF v_user.activity_status = 'Suspended' THEN\n        RETURN json_build_object('success', false, 'error', 'Your account has been suspended. Please contact the administrator.');\n    END IF;\n\n    v_password_match := (v_user.password_hash = crypt(p_password, v_user.password_hash));\n\n    IF v_password_match THEN\n        RETURN json_build_object(\n            'success', true,\n            'user', json_build_object(\n                'id', v_user.id,\n                'ilj_id', v_user.ilj_id,\n                'first_name', v_user.first_name,\n                'last_name', v_user.last_name,\n                'email', v_user.email,\n                'mobile_number', v_user.mobile_number,\n                'rank', v_user.rank,\n                'designation', v_user.designation,\n                'secondary_designation', v_user.secondary_designation,\n                'team_leader_for', v_user.team_leader_for,\n                'is_it_admin', v_user.is_it_admin,\n                'is_onboarding_team', v_user.is_onboarding_team,\n                'is_pod_team', v_user.is_pod_team,\n                'onboarding_status', v_user.onboarding_status,\n                'assigned_pod', v_user.assigned_pod,\n                'activity_status', v_user.activity_status,\n                'managed_projects', (\n                    SELECT coalesce(json_agg(p), '[]'::json)\n                    FROM projects p \n                    WHERE p.manager_id = v_user.id OR v_user.id = ANY(p.sub_head_ids)\n                )\n            )\n        );\n    ELSE\n        RETURN json_build_object('success', false, 'error', 'Invalid ILJ ID or password');\n    END IF;\nEND;\n$function$;\n\n-- 5. Update force_sync_auth_password to block suspended volunteers\nCREATE OR REPLACE FUNCTION public.force_sync_auth_password(p_ilj_id text, p_password text)\n RETURNS json\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'auth', 'extensions'\nAS $function$\nDECLARE\n    v_volunteer record;\n    v_user_exists boolean;\nBEGIN\n    SELECT id, email, password_hash, first_name, last_name, activity_status \n    INTO v_volunteer\n    FROM public.volunteers\n    WHERE upper(ilj_id) = upper(p_ilj_id);\n\n    IF v_volunteer.id IS NULL THEN\n        RETURN json_build_object('success', false, 'error', 'Volunteer not found');\n    END IF;\n\n    IF v_volunteer.activity_status = 'Suspended' THEN\n        RETURN json_build_object('success', false, 'error', 'Your account has been suspended. Please contact the administrator.');\n    END IF;\n\n    SELECT EXISTS(SELECT 1 FROM auth.users WHERE id = v_volunteer.id) INTO v_user_exists;\n\n    IF v_user_exists THEN\n        UPDATE auth.users\n        SET encrypted_password = v_volunteer.password_hash,\n            updated_at = now()\n        WHERE id = v_volunteer.id;\n        \n        RETURN json_build_object('success', true, 'action', 'updated');\n    ELSE\n        INSERT INTO auth.users (\n            instance_id,\n            id,\n            aud,\n            role,\n            email,\n            encrypted_password,\n            email_confirmed_at,\n            raw_app_meta_data,\n            raw_user_meta_data,\n            created_at,\n            updated_at\n        ) VALUES (\n            '00000000-0000-0000-0000-000000000000',\n            v_volunteer.id,\n            'authenticated',\n            'authenticated',\n            v_volunteer.email,\n            v_volunteer.password_hash,\n            now(),\n            '{\\"provider\\":\\"email\\",\\"providers\\":[\\"email\\"]}',\n            json_build_object(\n                'ilj_id', upper(p_ilj_id),\n                'first_name', v_volunteer.first_name,\n                'last_name', v_volunteer.last_name\n            ),\n            now(),\n            now()\n        );\n        \n        INSERT INTO auth.identities (\n            id,\n            user_id,\n            identity_data,\n            provider,\n            last_sign_in_at,\n            created_at,\n            updated_at\n        ) VALUES (\n            v_volunteer.id,\n            v_volunteer.id,\n            json_build_object('sub', v_volunteer.id, 'email', v_volunteer.email),\n            'email',\n            now(),\n            now(),\n            now()\n        );\n\n        RETURN json_build_object('success', true, 'action', 'created');\n    END IF;\n\nEXCEPTION WHEN OTHERS THEN\n    RETURN json_build_object('success', false, 'error', SQLERRM);\nEND;\n$function$;\n\nGRANT EXECUTE ON FUNCTION public.suspend_volunteer(uuid) TO authenticated, service_role, anon;\nGRANT EXECUTE ON FUNCTION public.reactivate_volunteer(uuid) TO authenticated, service_role, anon;\nGRANT EXECUTE ON FUNCTION public.terminate_volunteer(uuid) TO authenticated, service_role, anon;\nGRANT EXECUTE ON FUNCTION public.login_volunteer(text, text) TO anon, authenticated, service_role;\nGRANT EXECUTE ON FUNCTION public.force_sync_auth_password(text, text) TO anon, authenticated, service_role;"}	account_suspension_and_termination	meets.studentlife@gmail.com	\N	\N
20261016185657	{"CREATE TABLE IF NOT EXISTS public.questions (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    name TEXT NOT NULL,\n    phone_no TEXT NOT NULL,\n    email TEXT,\n    gender TEXT,\n    address TEXT,\n    age INTEGER,\n    question TEXT NOT NULL,\n    status TEXT DEFAULT 'pending',\n    admin_reply TEXT,\n    replied_at TIMESTAMP WITH TIME ZONE,\n    created_at TIMESTAMP WITH TIME ZONE DEFAULT now()\n);\n\nALTER TABLE public.questions ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \\"Allow public insert questions\\"\n    ON public.questions FOR INSERT\n    WITH CHECK (true);\n\nCREATE POLICY \\"Allow public/admin select questions\\"\n    ON public.questions FOR SELECT\n    USING (true);\n\nCREATE POLICY \\"Allow admin update questions\\"\n    ON public.questions FOR UPDATE\n    USING (true)\n    WITH CHECK (true);\n\nCREATE POLICY \\"Allow admin delete questions\\"\n    ON public.questions FOR DELETE\n    USING (true);\n"}	create_questions_table	meets.studentlife@gmail.com	\N	\N
20261016190501	{"CREATE TABLE IF NOT EXISTS public.samarpanam_nominations (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    \n    -- Nominator Details\n    nominator_name TEXT NOT NULL,\n    nominator_mobile TEXT NOT NULL,\n    nominator_age INTEGER,\n    nominator_gender TEXT,\n    nominator_address TEXT NOT NULL,\n    relationship_with_nominee TEXT NOT NULL,\n    relationship_other TEXT,\n    \n    -- Nominee Details\n    nominee_name TEXT NOT NULL,\n    nominee_mobile TEXT NOT NULL,\n    nominee_age INTEGER,\n    nominee_address TEXT NOT NULL,\n    nominee_marital_status TEXT NOT NULL,\n    nominee_marital_status_other TEXT,\n    nominee_wife_name TEXT NOT NULL,\n    nominee_wife_mobile TEXT,\n    \n    -- Seva Details\n    seva_areas TEXT[] NOT NULL DEFAULT '{}',\n    seva_areas_other TEXT,\n    sangh_name TEXT,\n    sangh_head_contact TEXT,\n    involvement_duration TEXT NOT NULL,\n    hours_per_week TEXT NOT NULL,\n    total_hours_till_date NUMERIC,\n    contribution_description TEXT NOT NULL,\n    initiatives_achievements TEXT,\n    \n    -- Wife's Support\n    wife_support_description TEXT,\n    wife_incident_story TEXT,\n    \n    -- Declarations & Consent\n    declaration_authenticity BOOLEAN DEFAULT true,\n    consent_verification BOOLEAN DEFAULT true,\n    \n    -- Admin & Status\n    status TEXT DEFAULT 'submitted',\n    admin_notes TEXT,\n    created_at TIMESTAMP WITH TIME ZONE DEFAULT now()\n);\n\nALTER TABLE public.samarpanam_nominations ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \\"Allow public insert samarpanam nominations\\"\n    ON public.samarpanam_nominations FOR INSERT\n    WITH CHECK (true);\n\nCREATE POLICY \\"Allow select samarpanam nominations\\"\n    ON public.samarpanam_nominations FOR SELECT\n    USING (true);\n\nCREATE POLICY \\"Allow update samarpanam nominations\\"\n    ON public.samarpanam_nominations FOR UPDATE\n    USING (true)\n    WITH CHECK (true);\n\nCREATE POLICY \\"Allow delete samarpanam nominations\\"\n    ON public.samarpanam_nominations FOR DELETE\n    USING (true);\n"}	create_samarpanam_nominations_table	meets.studentlife@gmail.com	\N	\N
